      text0 = this.getContents().suffix(2) and
      text = text0.prefix(text0.length() - 2)
    ) and
    // The /* */ comment must be a single-line comment
    not text.matches("%\n%")
  }

  /** Gets the text in this comment, excluding the leading //. */
  string getText() { result = text }
}

